      width: 1.2rem;
      height: 1.2rem;
      margin-top: 0.1rem;
      accent-color: var(--primary);
      flex: none;
    }

    .choice label {
      font-weight: 600;
      line-height: 1.5;
      cursor: pointer;
    }

    .choice small {
      display: block;
      margin-top: 0.2rem;
      color: var(--muted);
      font-weight: 500;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      padding-top: 0.5rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      background: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(79, 70, 229, 0.25);
    }

    button:hover {
      background: linear-gradient(135deg, var(--primary-strong) 0%, #6d28d9 100%);
    }

    button:focus-visible,
    .choice input:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .results {
      min-height: 3.5rem;
      padding: 1rem 1.1rem;
      border: 1px solid rgba(20, 184, 166, 0.18);
      border-radius: var(--radius-md);
      background: rgba(20, 184, 166, 0.08);
      color: var(--text);
    }

    .results h2 {
      margin: 0 0 0.6rem;
      font-size: 1rem;
