    .results p,
    .results ul {
      margin: 0;
      line-height: 1.6;
    }

    .results ul {
      padding-left: 1.2rem;
    }

    .results li + li {
      margin-top: 0.4rem;
    }

    @media (max-width: 640px) {
      .page-shell {
