415.   <script>
416.     const quizForm = document.getElementById("quiz-form");
417.     const results = document.getElementById("results");
418.     const questionNames = ["question-1", "question-2", "question-3"];
419. 
420.     function updateQuestionState(questionName, showError) {
421.       const field = document.querySelector(`[data-question="${questionName}"]`);
422.       const fieldset = field.querySelector("fieldset");
423.       const error = document.getElementById(`${questionName}-error`);
424.       const checked = field.querySelectorAll(`input[name="${questionName}"]:checked`).length > 0;
425.       const describedBy = [];
426. 
427.       if (questionName === "question-1") {
428.         describedBy.push("question-1-help");
429.       }
430. 
431.       if (!checked && showError) {
432.         error.hidden = false;
433.         field.classList.add("is-invalid");
434.         describedBy.push(`${questionName}-error`);
435.       } else {
436.         error.hidden = true;
437.         field.classList.remove("is-invalid");
438.       }
439. 
440.       if (describedBy.length > 0) {
441.         fieldset.setAttribute("aria-describedby", describedBy.join(" "));
442.       } else {
443.         fieldset.removeAttribute("aria-describedby");
444.       }
445. 
446.       return checked;
447.     }
448. 
449.     questionNames.forEach((questionName) => {
450.       const inputs = document.querySelectorAll(`input[name="${questionName}"]`);
451.       inputs.forEach((input) => {
452.         input.addEventListener("change", () => {
453.           updateQuestionState(questionName, false);
454.         });
455.       });
456.     });
457. 
458.     quizForm.addEventListener("submit", (event) => {
459.       event.preventDefault();
460. 
461.       const invalidQuestions = questionNames.filter((questionName) => !updateQuestionState(questionName, true));
462. 
463.       if (invalidQuestions.length > 0) {
464.         const firstInvalidInput = document.querySelector(`input[name="${invalidQuestions[0]}"]`);
465.         firstInvalidInput.focus();
466.         results.innerHTML = "<p>Please answer every question before submitting the quiz.</p>";
467.         return;
468.       }
469. 
470.       const summaries = questionNames.map((questionName, index) => {
471.         const selected = Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`)).map((input) => input.value);
472.         return `<li><strong>Question ${index + 1}:</strong> ${selected.join(", ")}</li>`;
473.       });
474. 
475.       results.innerHTML = `
476.         <h2>Selections submitted</h2>
477.         <ul>${summaries.join("")}</ul>
478.       `;
479.     });
480.   </script>
