     const results = document.getElementById("results");
     const questionNames = ["question-1", "question-2", "question-3"];

     function updateQuestionState(questionName, showError) {
       const field = document.querySelector(`[data-question="${questionName}"]`);
       const fieldset = field.querySelector("fieldset");
       const error = document.getElementById(`${questionName}-error`);
       const checked = field.querySelectorAll(`input[name="${questionName}"]:checked`).length > 0;
       const describedBy = [];

       if (questionName === "question-1") {
         describedBy.push("question-1-help");
       }

       if (!checked && showError) {
         error.hidden = false;
         field.classList.add("is-invalid");
         describedBy.push(`${questionName}-error`);
       } else {
         error.hidden = true;
         field.classList.remove("is-invalid");
       }

       if (describedBy.length > 0) {
         fieldset.setAttribute("aria-describedby", describedBy.join(" "));
       } else {
         fieldset.removeAttribute("aria-describedby");
       }

       return checked;
     }

     questionNames.forEach((questionName) => {
       const inputs = document.querySelectorAll(`input[name="${questionName}"]`);
       inputs.forEach((input) => {
         input.addEventListener("change", () => {
           updateQuestionState(questionName, false);
         });
       });
     });

     quizForm.addEventListener("submit", (event) => {
       event.preventDefault();

       const invalidQuestions = questionNames.filter((questionName) => !updateQuestionState(questionName, true));

       if (invalidQuestions.length > 0) {
         const firstInvalidInput = document.querySelector(`input[name="${invalidQuestions[0]}"]`);
         firstInvalidInput.focus();
         results.innerHTML = "<p>Please answer every question before submitting the quiz.</p>";
         return;
       }

       const summaries = questionNames.map((questionName, index) => {
         const selected = Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`)).map((input) => input.value);
         return `<li><strong>Question ${index + 1}:</strong> ${selected.join(", ")}</li>`;
       });

       results.innerHTML = `
         <h2>Selections submitted</h2>
         <ul>${summaries.join("")}</ul>
       `;
     });
   </script>
