         <div class="form-field" data-question="question-1">
           <fieldset aria-describedby="question-1-help">
             <legend>1. Which of these are commonly compiled programming languages?</legend>
             <p id="question-1-help" class="help-text">
               Help text: Select every language that is typically compiled ahead of time or to an intermediate target before it runs.
             </p>
             <div class="choices">
               <div class="choice">
                 <input id="q1-c" type="checkbox" name="question-1" value="C">
                 <label for="q1-c">C<small>Often compiled directly to machine code.</small></label>
               </div>
               <div class="choice">
                 <input id="q1-go" type="checkbox" name="question-1" value="Go">
                 <label for="q1-go">Go<small>Usually built into a standalone binary.</small></label>
               </div>
               <div class="choice">
                 <input id="q1-python" type="checkbox" name="question-1" value="Python">
                 <label for="q1-python">Python<small>Most commonly interpreted.</small></label>
               </div>
               <div class="choice">
                 <input id="q1-rust" type="checkbox" name="question-1" value="Rust">
                 <label for="q1-rust">Rust<small>Compiled ahead of time with a strong focus on safety.</small></label>
               </div>
             </div>
             <p id="question-1-error" class="field-error" hidden>Error: Select at least one answer for question 1.</p>
           </fieldset>
         </div>

         <div class="form-field" data-question="question-2">
           <fieldset>
             <legend>2. Which of these are used to structure or style web pages rather than to build general-purpose application logic?</legend>
             <div class="choices">
               <div class="choice">
                 <input id="q2-html" type="checkbox" name="question-2" value="HTML">
                 <label for="q2-html">HTML<small>Defines document structure for the web.</small></label>
               </div>
               <div class="choice">
                 <input id="q2-css" type="checkbox" name="question-2" value="CSS">
                 <label for="q2-css">CSS<small>Controls presentation and layout.</small></label>
               </div>
               <div class="choice">
                 <input id="q2-python" type="checkbox" name="question-2" value="Python">
                 <label for="q2-python">Python<small>A general-purpose programming language.</small></label>
               </div>
               <div class="choice">
                 <input id="q2-typescript" type="checkbox" name="question-2" value="TypeScript">
                 <label for="q2-typescript">TypeScript<small>A typed programming language for JavaScript ecosystems.</small></label>
               </div>
             </div>
             <p id="question-2-error" class="field-error" hidden>Error: Select at least one answer for question 2.</p>
           </fieldset>
         </div>

         <div class="form-field" data-question="question-3">
           <fieldset>
             <legend>3. Which of these languages commonly run on the Java Virtual Machine (JVM)?</legend>
             <div class="choices">
               <div class="choice">
                 <input id="q3-java" type="checkbox" name="question-3" value="Java">
                 <label for="q3-java">Java<small>The original mainstream JVM language.</small></label>
               </div>
               <div class="choice">
                 <input id="q3-kotlin" type="checkbox" name="question-3" value="Kotlin">
                 <label for="q3-kotlin">Kotlin<small>A modern JVM language also used for Android.</small></label>
               </div>
               <div class="choice">
                 <input id="q3-scala" type="checkbox" name="question-3" value="Scala">
                 <label for="q3-scala">Scala<small>A language that blends object-oriented and functional styles.</small></label>
               </div>
               <div class="choice">
                 <input id="q3-ruby" type="checkbox" name="question-3" value="Ruby">
                 <label for="q3-ruby">Ruby<small>Typically runs on MRI or related interpreters instead.</small></label>
               </div>
             </div>
             <p id="question-3-error" class="field-error" hidden>Error: Select at least one answer for question 3.</p>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Submit quiz</button>
         </div>

         <section id="results" class="results" aria-live="polite" aria-atomic="true">
           <p>Your selected answers will appear here after you submit the quiz.</p>
         </section>
       </form>
     </section>
   </main>

   <script>
     const quizForm = document.getElementById("quiz-form");
     const results = document.getElementById("results");
     const questionNames = ["question-1", "question-2", "question-3"];

     function updateQuestionState(questionName, showError) {
       const field = document.querySelector(`[data-question="${questionName}"]`);
       const fieldset = field.querySelector("fieldset");
       const error = document.getElementById(`${questionName}-error`);
       const checked = field.querySelectorAll(`input[name="${questionName}"]:checked`).length > 0;
       const describedBy = [];

       if (questionName === "question-1") {
         describedBy.push("question-1-help");
       }

       if (!checked && showError) {
         error.hidden = false;
         field.classList.add("is-invalid");
         describedBy.push(`${questionName}-error`);
       } else {
         error.hidden = true;
         field.classList.remove("is-invalid");
       }

       if (describedBy.length > 0) {
         fieldset.setAttribute("aria-describedby", describedBy.join(" "));
       } else {
         fieldset.removeAttribute("aria-describedby");
       }

       return checked;
     }

     questionNames.forEach((questionName) => {
       const inputs = document.querySelectorAll(`input[name="${questionName}"]`);
       inputs.forEach((input) => {
         input.addEventListener("change", () => {
           updateQuestionState(questionName, false);
         });
       });
     });

     quizForm.addEventListener("submit", (event) => {
       event.preventDefault();

       const invalidQuestions = questionNames.filter((questionName) => !updateQuestionState(questionName, true));

       if (invalidQuestions.length > 0) {
         const firstInvalidInput = document.querySelector(`input[name="${invalidQuestions[0]}"]`);
         firstInvalidInput.focus();
         results.innerHTML = "<p>Please answer every question before submitting the quiz.</p>";
         return;
       }

       const summaries = questionNames.map((questionName, index) => {
         const selected = Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`)).map((input) => input.value);
         return `<li><strong>Question ${index + 1}:</strong> ${selected.join(", ")}</li>`;
       });

       results.innerHTML = `
         <h2>Selections submitted</h2>
         <ul>${summaries.join("")}</ul>
       `;
     });
   </script>
